{"query":"query GetCourseBySlugWithProgressions($slug: String!, $language: String!, $extended: Boolean!) {
  __typename
  courses(filter: {slug: {_eq: $slug}}) {
    __typename
    id
    slug
    ...CourseFields
    lessons {
      __typename
      id
      slug
      ...LessonFields
      progressions {
        __typename
        id
        is_complete
        lesson {
          __typename
          id
        }
      }
    }
    exam {
      __typename
      id
      badge {
        __typename
        id
        name
        url
        image_url
      }
    }
  }
  badges_earned(filter: {badge: {exam: {course: {slug: {_eq: $slug}}}}}) {
    __typename
    id
    date_earned
    date_issued
  }
}

fragment CourseFields on courses {
  __typename
  translations(filter: {languages_code: {code: {_eq: $language}}}) {
    __typename
    id
    title
    description @include(if: $extended)
    short_description @include(if: $extended)
    helpful_materials @include(if: $extended)
  }
  hero_image @include(if: $extended) {
    __typename
    id
  }
  hero_video_id @include(if: $extended)
  hero_video_provider @include(if: $extended)
  author @include(if: $extended)
  lessons_func @include(if: $extended) {
    __typename
    count
  }
  tags {
    __typename
    tags_id {
      __typename
      name
    }
  }
}

fragment LessonFields on lessons {
  __typename
  translations(filter: {languages_code: {code: {_eq: $language}}}) {
    __typename
    id
    title
    sections
  }
}","variables":{"slug":"quantum-computing-in-practice","language":"en-US","extended":false}}

{"query":"query GetLessonBySlugWithAttempts($lessonSlug: String, $courseSlug: String, $language: String!) {
  __typename
  lessons(filter: {slug: {_eq: $lessonSlug}, course: {slug: {_eq: $courseSlug}}}) {
    __typename
    id
    slug
    ...CompleteLessonFields
    multiple_choice_questions {
      __typename
      attempts(sort: "-date_created", limit: 1) {
        __typename
        id
        user
        status
        selected_options
      }
      attempts_func {
        __typename
        count
      }
    }
  }
}

fragment CompleteLessonFields on lessons {
  __typename
  translations(filter: {languages_code: {code: {_eq: $language}}}) {
    __typename
    id
    title
    short_description
    content
    sections
  }
  multiple_choice_questions {
    __typename
    id
    max_attempts
    multi_select
    question
    options {
      __typename
      id
      option
    }
  }
}","variables":{"lessonSlug":"introduction","courseSlug":"quantum-computing-in-practice","language":"en-US"}}

